import re,html
t=open('hint2019.xml').read()
m=re.search(r'<article-meta>.*?</article-meta>',t,re.S).group(0)
print(re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]+>',' ',m)))[:600])
t=re.sub(r'</p>','\n',t); t=html.unescape(re.sub('<[^>]+>','',t))
for s in re.split(r'(?<=[.])\s+',t):
    if re.search(r'RMSE|root mean square',s) and re.search(r'\d',s): print('*',s.strip()[:400])
" | head -30",
  "description": "Fetch Hinterreiter 2019 from Europe PMC and grep RMSE"
}

